contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (0)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        bool revertedNonZero;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedNonZero = true;
        } else {
            revertedNonZero = false;
        }

        bool revertedZero;
        c.go{value: 0}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedZero = true;
        } else {
            revertedZero = false;
        }

        assert(!(revertedNonZero && !revertedZero));
    }

    receive() external payable {
    }
}

